{
  "samples": [
    {
      "scenario_id": "top1_controlled_multiturn_v2_intent_change_travelguide_to_lifeexperience_002",
      "messages": [
        {
          "role": "user",
          "content": "第一次去成都，住宿选春熙路附近还是玉林路那边？带老人，想逛逛武侯祠和熊猫基地。"
        },
        {
          "role": "assistant",
          "content": "带老人的话更推荐春熙路，地铁换乘方便，去武侯祠、熊猫基地都有较顺的路线，附近吃饭购物也省腿脚。玉林路更有市井味道，但早上出门去熊猫基地会绕一些，老人容易累。"
        },
        {
          "role": "user",
          "content": "新家准备装一套智能家居，监理说开关不一定要全换，能推荐一下哪些设备值得先配吗？"
        }
      ],
      "scenario_summary": "从旅行住宿区域咨询切换为智能家居选购经验咨询"
    },
    {
      "scenario_id": "top1_controlled_multiturn_v2_intent_change_fooddiscovery_to_ticketservice_003",
      "messages": [
        {
          "role": "user",
          "content": "最近在控糖，早餐搭配上有没有什么注意？比如全麦面包和燕麦哪个更好？"
        },
        {
          "role": "assistant",
          "content": "主要看配料表，选整粒燕麦或纯全麦粉排第一的，别买糖和植脂末多的。可以再配点鸡蛋和绿叶菜，血糖会更稳。"
        },
        {
          "role": "user",
          "content": "那午餐想加点豆制品，豆腐和腐竹哪个更适合减脂期吃？"
        },
        {
          "role": "assistant",
          "content": "豆腐热量低、蛋白质好，腐竹热量偏高一点。减脂期优先选北豆腐或嫩豆腐，量控制在掌心大小就好。"
        },
        {
          "role": "user",
          "content": "晚餐经常没时间做，水煮虾配西兰花可以吗？还需要加主食吗？"
        },
        {
          "role": "assistant",
          "content": "可以，虾和西兰花都是好选择。但晚餐也要有适量主食，比如半根玉米或小半碗杂粮饭，再加一小勺油帮助吸收脂溶性维生素。"
        },
        {
          "role": "user",
          "content": "帮我查一下明天早上从宁波到绍兴的长途汽车票，最早一班是几点？还有余票吗？"
        }
      ],
      "scenario_summary": "从日常饮食搭配咨询切换为长途汽车票班次查询"
    }
  ]
}

